/**
 * Realistic pest photos (trimmed, ~220px, transparent PNG) inlined as base64 so
 * the quote Lambda can embed them at runtime — it cannot read the web
 * `apps/web/public/images/pest-*.png` assets, which ship only to the browser
 * bundle. Regenerate from those sources with the script in the commit that
 * added this file (trim alpha bbox, thumbnail to 220px, PNG optimize, base64).
 *
 * Keyed by pest; each carries its intrinsic pixel size so the renderer can
 * preserve aspect ratio. Used by renderQuotePdf for the coverage strip.
 */
export type PestArt = { b64: string; w: number; h: number; label: string };

export const PEST_ART: Record<string, PestArt> = {
  ants: { w: 144, h: 220, label: "Ants", b64: "" },
  spiders: { w: 137, h: 220, label: "Spiders", b64: "" },
  cockroaches: { w: 132, h: 220, label: "Cockroaches", b64: "" },
  mosquitoes: { w: 220, h: 199, label: "Mosquitoes", b64: "" },
  ticks: { w: 139, h: 220, label: "Ticks", b64: "" },
  fleas: { w: 107, h: 220, label: "Fleas", b64: "" },
  wasps: { w: 166, h: 220, label: "Wasps & Bees", b64: "" },
  rodents: { w: 220, h: 196, label: "Mice & Rats", b64: "" },
};
